const raw = $input.all()[0].json.text;

function extract(text, marker) {
  const start = text.indexOf('===' + marker + '===');
  if (start === -1) return "Section not found";
  const afterMarker = text.indexOf('\n', start) + 1;
  const nextMarker = text.indexOf('===', afterMarker);
  if (nextMarker === -1) return text.substring(afterMarker).trim();
  return text.substring(afterMarker, nextMarker).trim();
}

const date = $('Brett Persona').item.json.date;

return [{
  json: {
    investigation: extract(raw, 'VARIANT_A: INVESTIGATION'),
    narrative: extract(raw, 'VARIANT_B: NARRATIVE'),
    segment: extract(raw, 'VARIANT_C: SEGMENT'),
