var pf = $('Parse Final').item.json;
var chatIds = ["1240314255", "8509710128", "8727548584"];
var variants = [
  { label: 'INVESTIGATION (5-8 min)', text: pf.investigation },
  { label: 'NARRATIVE (5-6 min)', text: pf.narrative },
  { label: 'SEGMENT (4 min clip-ready)', text: pf.segment },
  { label: 'QUICK TAKE (90 sec)', text: pf.quickTake },
  { label: 'SOCIAL POSTS', text: pf.socialPosts }
];

var messages = [];
for (var i = 0; i < variants.length; i++) {
  var v = variants[i];
  var fullText = '\u2550\u2550\u2550 ' + v.label + ' \u2550\u2550\u2550\n\n' + (v.text || 'Section not generated');
  // Split at 4000 chars (Telegram limit is 4096)
  var chunks = [];
  var remaining = fullText;
  while (remaining.length > 0) {
    if (remaining.length <= 4000) {
      chunks.push(remaining);
      remaining = '';
    } else {
      var breakAt = remaining.lastIndexOf('\n', 4000);
      if (breakAt < 3000) breakAt = 4000;
      chunks.push(remaining.substring(0, breakAt));
      remaining = remaining.substring(breakAt);
    }
  }
  for (var c = 0; c < chunks.length; c++) {
    var suffix = chunks.length > 1 ? ' [' + (c + 1) + '/' + chunks.length + ']' : '';
    // Fan out to all chat IDs
    for (var ci = 0; ci < chatIds.length; ci++) {
      messages.push({ json: { text: chunks[c] + suffix, chat_id: chatIds[ci] } });
    }
  }
}
return messages;

